import React, { useState } from 'react';
import './PaymentForm.css';

const PaymentForm = () => {
  // Estado para el método de pago seleccionado: 'card', 'nequi', 'daviplata'
  const [paymentMethod, setPaymentMethod] = useState('card');
  const [formData, setFormData] = useState({}); // Datos dinámicos del formulario

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevState => ({
      ...prevState,
      [name]: value,
    }));
  };

  const handleMethodChange = (e) => {
    setPaymentMethod(e.target.value);
    setFormData({}); // Limpiar datos al cambiar de método
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log(`Método de Pago Seleccionado: ${paymentMethod}`);
    console.log('Datos de pago:', formData);

    // Aquí se enviaría la solicitud al backend y la pasarela de pagos real.
    alert(`Simulación de pago con ${paymentMethod} enviado.`);
  };

  /**
   * Función para renderizar los campos de formulario específicos para cada método.
   */
  const renderPaymentFields = () => {
    switch (paymentMethod) {
      case 'card':
        return (
          <>
            <div className="form-group">
              <label htmlFor="cardNumber">Número de Tarjeta</label>
              <input
                type="text"
                id="cardNumber"
                name="cardNumber"
                onChange={handleChange}
                placeholder="XXXX XXXX XXXX XXXX"
                maxLength="19"
                required
              />
            </div>

            <div className="form-row">
              <div className="form-group half-width">
                <label htmlFor="expiryDate">Fecha de Vencimiento (MM/AA)</label>
                <input
                  type="text"
                  id="expiryDate"
                  name="expiryDate"
                  onChange={handleChange}
                  placeholder="MM/AA"
                  maxLength="5"
                  required
                />
              </div>

              <div className="form-group half-width">
                <label htmlFor="cvv">CVV</label>
                <input
                  type="password"
                  id="cvv"
                  name="cvv"
                  onChange={handleChange}
                  placeholder="123"
                  maxLength="4"
                  required
                />
              </div>
            </div>

            <div className="form-group">
              <label htmlFor="cardHolderName">Nombre del Titular</label>
              <input
                type="text"
                id="cardHolderName"
                name="cardHolderName"
                onChange={handleChange}
                placeholder="Nombre Apellido"
                required
              />
            </div>
          </>
        );

      case 'nequi':
      case 'daviplata':
        const labelText = paymentMethod === 'nequi' ? 'Número Nequi' : 'Número DaviPlata';
        const placeholderText = paymentMethod === 'nequi' ? '300 XXX XX XX' : '300 XXX XX XX';

        return (
          <>
            <div className="form-group">
              <label htmlFor="phone">{labelText}</label>
              <input
                type="tel"
                id="phone"
                name="phone"
                onChange={handleChange}
                placeholder={placeholderText}
                maxLength="10"
                required
              />
              <p className="small-note">
                Serás redirigido a la aplicación móvil o web para confirmar la transacción.
              </p>
            </div>
          </>
        );

      default:
        return <p>Selecciona un método de pago.</p>;
    }
  };

  return (
    <div className="payment-container">
      <h2>💸 Checkout Seguro</h2>
      <form className="payment-form" onSubmit={handleSubmit}>

        {/* --- SELECCIÓN DEL MÉTODO DE PAGO --- */}
        <div className="form-group">
          <label htmlFor="paymentMethod">Selecciona tu método de pago</label>
          <select 
            id="paymentMethod" 
            name="paymentMethod" 
            value={paymentMethod} 
            onChange={handleMethodChange}
            className="select-method"
          >
            <option value="card">💳 Tarjeta de Crédito/Débito</option>
            <option value="nequi">📲 Nequi</option>
            <option value="daviplata">🧡 DaviPlata</option>
          </select>
        </div>

        {/* --- CAMPOS DINÁMICOS --- */}
        <div className="dynamic-fields">
          {renderPaymentFields()}
        </div>

        <button type="submit" className="pay-button">
          Pagar $99.99 COP
        </button>

        <p className="security-note">
          🔒 Al continuar, aceptas los Términos y Condiciones.
        </p>
      </form>
    </div>
  );
};

export default PaymentForm;
